import{I as e,T as t,i as n,w as r}from"./app-DKh1lFL5.js";var i=JSON.parse(`{"path":"/document/Kubernetes/nerdctl%20%E9%83%A8%E7%BD%B2%E5%8F%8A%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97.html","title":"nerdctl 部署及使用指南","lang":"zh-CN","frontmatter":{"title":"nerdctl 部署及使用指南","icon":"circle-info","order":1,"category":["Linux"],"tag":["Linux","kubernetes","Docker","nerdctl","container","云原生","运维"],"date":"2026-10-24T00:00:00.000Z","isOriginal":true,"pageview":true,"article":true,"breadcrumb":false,"comment":true,"description":"👨‍🎓博主简介 🏅CSDN博客专家 🏅云计算领域优质创作者 🏅华为云开发者社区专家博主 🏅阿里云开发者社区专家博主 💊交流社区：运维交流社区 欢迎大家的加入！ 🐋 希望大家多多支持，我们一起进步！😄 🎉如果文章对你有帮助的话，欢迎 点赞 👍🏻 评论 💬 收藏 ⭐️ 加关注+💗 一、概述 1.1 nerdctl 是什么？ ne...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"nerdctl 部署及使用指南\\",\\"image\\":[\\"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133315613.jpeg\\",\\"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133319920.png\\",\\"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133329909.png\\",\\"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133333444.png\\",\\"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133355800.png\\",\\"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133402705.png\\"],\\"datePublished\\":\\"2026-10-24T00:00:00.000Z\\",\\"dateModified\\":\\"2026-10-24T05:39:04.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"𝑴𝒓.𝑳𝒊𝒖𝒄𝒚\\",\\"url\\":\\"https://liuchenyang.top\\"}]}"],["meta",{"property":"og:url","content":"https://liuchenyang.top/ToLiucyLinux/document/Kubernetes/nerdctl%20%E9%83%A8%E7%BD%B2%E5%8F%8A%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97.html"}],["meta",{"property":"og:site_name","content":"ToLiucyLinux"}],["meta",{"property":"og:title","content":"nerdctl 部署及使用指南"}],["meta",{"property":"og:description","content":"👨‍🎓博主简介 🏅CSDN博客专家 🏅云计算领域优质创作者 🏅华为云开发者社区专家博主 🏅阿里云开发者社区专家博主 💊交流社区：运维交流社区 欢迎大家的加入！ 🐋 希望大家多多支持，我们一起进步！😄 🎉如果文章对你有帮助的话，欢迎 点赞 👍🏻 评论 💬 收藏 ⭐️ 加关注+💗 一、概述 1.1 nerdctl 是什么？ ne..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133315613.jpeg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-24T05:39:04.000Z"}],["meta",{"property":"article:tag","content":"运维"}],["meta",{"property":"article:tag","content":"云原生"}],["meta",{"property":"article:tag","content":"container"}],["meta",{"property":"article:tag","content":"nerdctl"}],["meta",{"property":"article:tag","content":"Docker"}],["meta",{"property":"article:tag","content":"kubernetes"}],["meta",{"property":"article:tag","content":"Linux"}],["meta",{"property":"article:published_time","content":"2026-10-24T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-24T05:39:04.000Z"}],["link",{"rel":"canonical","href":"https://liuchenyang.top/document/Kubernetes/nerdctl%20%E9%83%A8%E7%BD%B2%E5%8F%8A%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97.html"}]]},"git":{"createdTime":1792820344000,"updatedTime":1792820344000,"contributors":[{"name":"liuchenyang","username":"liuchenyang","email":"2162059863@qq.com","commits":1,"url":"https://github.com/liuchenyang"}]},"readingTime":{"minutes":11.88,"words":3564},"filePathRelative":"document/Kubernetes/nerdctl 部署及使用指南.md","excerpt":"<blockquote>\\n<p>👨‍🎓<strong>博主简介</strong></p>\\n<p>  🏅<a href=\\"https://blog.csdn.net/liu_chen_yang?type=blog\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">CSDN博客专家</a><br>\\n  🏅<a href=\\"https://blog.csdn.net/liu_chen_yang?type=blog\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">云计算领域优质创作者</a><br>\\n  🏅<a href=\\"https://bbs.huaweicloud.com/community/usersnew/id_1661843828089234\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">华为云开发者社区专家博主</a><br>\\n  🏅<a href=\\"https://developer.aliyun.com/profile/7yu26jk3lfqxg\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">阿里云开发者社区专家博主</a><br>\\n💊<strong>交流社区：</strong><a href=\\"https://bbs.csdn.net/forums/lcy\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">运维交流社区</a> 欢迎大家的加入！<br>\\n🐋 希望大家多多支持，我们一起进步！😄<br>\\n🎉如果文章对你有帮助的话，欢迎 点赞 👍🏻 评论 💬 收藏 ⭐️ 加关注+💗</p>\\n</blockquote>","copyright":"著作权归 Mr.Liucy 所有，本站内容遵循 MIT 协议，转载请注明出处。\\n原文链接：https://liuchenyang.top/document/Kubernetes/nerdctl%20%E9%83%A8%E7%BD%B2%E5%8F%8A%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97.html","autoDesc":true}`),a={name:`nerdctl 部署及使用指南.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<blockquote><p>👨‍🎓<strong>博主简介</strong></p><p>  🏅<a href="https://blog.csdn.net/liu_chen_yang?type=blog" target="_blank" rel="noopener noreferrer">CSDN博客专家</a><br>   🏅<a href="https://blog.csdn.net/liu_chen_yang?type=blog" target="_blank" rel="noopener noreferrer">云计算领域优质创作者</a><br>   🏅<a href="https://bbs.huaweicloud.com/community/usersnew/id_1661843828089234" target="_blank" rel="noopener noreferrer">华为云开发者社区专家博主</a><br>   🏅<a href="https://developer.aliyun.com/profile/7yu26jk3lfqxg" target="_blank" rel="noopener noreferrer">阿里云开发者社区专家博主</a><br> 💊<strong>交流社区：</strong><a href="https://bbs.csdn.net/forums/lcy" target="_blank" rel="noopener noreferrer">运维交流社区</a> 欢迎大家的加入！<br> 🐋 希望大家多多支持，我们一起进步！😄<br> 🎉如果文章对你有帮助的话，欢迎 点赞 👍🏻 评论 💬 收藏 ⭐️ 加关注+💗</p></blockquote><hr><figure><img src="https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133315613.jpeg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="一、概述" tabindex="-1"><a class="header-anchor" href="#一、概述"><span>一、概述</span></a></h2><h3 id="_1-1-nerdctl-是什么" tabindex="-1"><a class="header-anchor" href="#_1-1-nerdctl-是什么"><span>1.1 nerdctl 是什么？</span></a></h3><p>nerdctl 是 containerd 官方社区维护的一个 CLI 工具，定位是 <strong>&quot;Docker 兼容的 containerd 命令行客户端&quot;</strong>。简单来说，它让你能用几乎和 Docker 一模一样的命令去操作 containerd。</p><p>随着 Kubernetes 在 v1.24 版本中正式移除 <code>Docker</code>，containerd 已成为容器运行时的事实标准，而 <code>nerdctl</code> 则填补了 containerd 原生客户端 <code>ctr</code> 缺乏用户友好性的空白。</p><p>相较于 <code>ctr</code> 仅面向调试场景、命令晦涩难用的特点，nerdctl 提供了与 Docker 几乎一致的命令体验，支持 <code>run</code>、<code>build</code>、<code>compose</code>、<code>login</code> 等完整操作链，同时继承了 containerd 的命名空间机制，能够直接管理 Kubernetes 命名空间下的容器。本文将从部署、基础用法、Kubernetes 调试、Rootless 模式等维度，系统介绍 nerdctl 的实践方法。</p><h3 id="_1-2-nerdctl-官方" tabindex="-1"><a class="header-anchor" href="#_1-2-nerdctl-官方"><span>1.2 nerdctl 官方</span></a></h3><ul><li>官方文档地址：<a href="https://github.com/containerd/nerdctl/tree/main/docs" target="_blank" rel="noopener noreferrer">https://github.com/containerd/nerdctl/tree/main/docs</a> 这里汇集了命令参考、配置说明、IPFS、GPU 等全部官方文档。‌‌</li><li>官方源码地址：<a href="https://github.com/containerd/nerdctl" target="_blank" rel="noopener noreferrer">https://github.com/containerd/nerdctl</a></li><li>二进制安装包官方下载地址：<a href="https://github.com/containerd/nerdctl/releases" target="_blank" rel="noopener noreferrer">https://github.com/containerd/nerdctl/releases</a></li></ul><h2 id="二、nerdctl-服务部署" tabindex="-1"><a class="header-anchor" href="#二、nerdctl-服务部署"><span>二、nerdctl 服务部署</span></a></h2><p><strong>操作环境：</strong></p><ul><li>操作系统：ubuntu24.04</li></ul><h3 id="_2-1-安装方式选择" tabindex="-1"><a class="header-anchor" href="#_2-1-安装方式选择"><span>2.1 安装方式选择</span></a></h3><blockquote><p>二进制安装包官方下载地址：<a href="https://github.com/containerd/nerdctl/releases" target="_blank" rel="noopener noreferrer">https://github.com/containerd/nerdctl/releases</a></p></blockquote><p>nerdctl 提供两种发布包：</p><ul><li><strong><code>nerdctl-full-&lt;VERSION&gt;-linux-amd64.tar.gz</code></strong>：包含 nerdctl 及其全部依赖（containerd 、CNI、BuildKit、RootlessKit 等），适合快速搭建完整环境，默认在官方下载地址是看不到的，需要点最下面的<code>Show all 17 assets</code>才能展示出来所有的安装包，就包含此安装包；</li><li><strong><code>nerdctl-&lt;VERSION&gt;-linux-amd64.tar.gz</code></strong>：仅含 nerdctl 二进制文件，适合已有 containerd 环境的场景</li></ul><figure><img src="https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133319920.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>推荐做法</strong>：对于大多数场景，直接下载 full 包并解压至 <code>/usr/local</code>，可一次性配齐所有工具。</p><p>我这里为空环境，只有一个操作系统，所以就拿<code>nerdctl-full-&lt;VERSION&gt;-linux-amd64.tar.gz</code>的包进行安装了；</p><h3 id="_2-2-下载并安装-nerdctl-服务" tabindex="-1"><a class="header-anchor" href="#_2-2-下载并安装-nerdctl-服务"><span>2.2 下载并安装 nerdctl 服务</span></a></h3><p>选择自己所需的版本及系统架构进行对应下载；</p><p>下载方式可使用<code>wget</code>下载或直接下载手动上传到服务器上；</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用wget命令下载</span></span>
<span class="line"><span style="color:#61AFEF;">wget</span><span style="color:#98C379;"> https://github.com/containerd/nerdctl/releases/download/v2.4.0/nerdctl-full-2.4.0-linux-amd64.tar.gz</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 解压到 /usr/local</span></span>
<span class="line"><span style="color:#61AFEF;">tar</span><span style="color:#98C379;"> xf</span><span style="color:#98C379;"> nerdctl-full-2.4.0-linux-amd64.tar.gz</span><span style="color:#D19A66;"> -C</span><span style="color:#98C379;"> /usr/local/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 验证</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> version</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133329909.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>有个报错，没关系，这个是因为<code>containerd</code>服务没有启动，<code>nerdctl</code>连接不上才会报错；</p><hr><p><code>nerdctl-full</code> 二进制包解压后的目录结构可以分为四大块，下面逐一说明。</p><ul><li>整体结构</li></ul><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">./nerdctl/</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> bin/</span><span style="color:#7F848E;font-style:italic;">                  # 所有可执行二进制</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> lib/systemd/system/</span><span style="color:#7F848E;font-style:italic;">   # systemd 服务单元文件</span></span>
<span class="line"><span style="color:#61AFEF;">├──</span><span style="color:#98C379;"> libexec/cni/</span><span style="color:#7F848E;font-style:italic;">          # CNI 网络插件</span></span>
<span class="line"><span style="color:#61AFEF;">└──</span><span style="color:#98C379;"> share/doc/</span><span style="color:#7F848E;font-style:italic;">            # 文档</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ol><li><code>bin/</code> —— 核心可执行文件</li></ol><p>这是最重要的一块，包含了运行容器所需的全部二进制。按功能可分为几类：</p><p><strong>容器运行时与客户端</strong></p><ul><li><code>containerd</code> —— 容器运行时守护进程（服务端，就是之前报错说没启动的那个）</li><li><code>containerd-shim-runc-v2</code> —— 容器进程的 shim，负责与 runc 交互</li><li><code>runc</code> —— 真正创建和运行容器的底层工具</li><li><code>ctr</code> —— containerd 自带的底层 CLI（调试用，难用）</li><li><code>nerdctl</code> —— 本文的主角，Docker 风格的 CLI</li></ul><p><strong>镜像构建相关</strong></p><ul><li><code>buildkitd</code> —— 镜像构建的守护进程</li><li><code>buildctl</code> —— BuildKit 的客户端</li><li><code>buildg</code> —— BuildKit 的调试工具</li></ul><p><strong>Rootless 相关</strong></p><ul><li><code>containerd-rootless.sh</code> —— Rootless 模式的启动脚本</li><li><code>containerd-rootless-setuptool.sh</code> —— Rootless 模式一键安装脚本</li><li><code>rootlesskit</code> / <code>rootlessctl</code> —— Rootless 的核心工具</li><li><code>bypass4netns</code> / <code>bypass4netnsd</code> —— Rootless 网络加速</li><li><code>fuse-overlayfs</code> / <code>containerd-fuse-overlayfs-grpc</code> —— 无 root 时的存储驱动</li></ul><p><strong>其他辅助</strong></p><ul><li><code>tini</code> —— 轻量 init 进程</li><li><code>stargz</code> 系列、<code>ctd-decoder</code> 等 —— 镜像加速相关（lazy pulling）</li><li><code>gomodjail</code>、<code>nerdctl.gomodjail</code> —— 权限隔离相关</li></ul><p>其中很多 <code>buildkit-cni-*</code> 是<strong>符号链接</strong>，指向 <code>../libexec/cni/</code> 下的真实插件，方便 BuildKit 构建时调用网络。</p><ol start="2"><li><code>lib/systemd/system/</code> —— 服务单元文件</li></ol><p>官方提供的 systemd 服务定义，默认咱们解压到<code>/usr/local</code>后就可以直接使用<code>systemctl</code>启动了：</p><ul><li><code>containerd.service</code> —— containerd 的 systemd 服务</li><li><code>buildkit.service</code> —— BuildKit 的 systemd 服务</li><li><code>stargz-snapshotter.service</code> —— stargz 快照器的服务</li></ul><ol start="3"><li><code>libexec/cni/</code> —— CNI 网络插件</li></ol><p>容器网络的核心插件，<code>nerdctl run</code> 创建 bridge 网络时依赖它们：</p><ul><li><code>bridge</code>、<code>host-local</code>、<code>loopback</code>、<code>portmap</code> 等是<strong>最常用</strong>的</li><li><code>bandwidth</code>、<code>firewall</code>、<code>tuning</code>、<code>vlan</code>、<code>macvlan</code> 等用于高级网络配置</li><li><code>LICENSE</code>、<code>README.md</code> 是说明文件</li></ul><p>nerdctl 默认会在 <code>/opt/cni/bin</code> 或 <code>/usr/local/libexec/cni</code> 下查找这些插件。如果路径不对，容器可能起不来（报找不到 CNI 插件）。</p><ol start="4"><li><code>share/doc/</code> —— 文档</li></ol><p>官方文档的离线副本，对于写文章很有参考价值：</p><ul><li><code>nerdctl/README.md</code> —— nerdctl 主文档</li><li><code>nerdctl/docs/</code> —— 各专题文档，如 <code>rootless.md</code>、<code>build.md</code>、<code>compose.md</code>、<code>registry.md</code>、<code>faq.md</code>、<code>config.md</code> 等</li><li><code>nerdctl-full/README.md</code> —— full 包的说明</li><li><code>nerdctl-full/SHA256SUMS</code> —— 校验和</li></ul><h3 id="_2-3-配置-containerd-使用-systemd-cgroup" tabindex="-1"><a class="header-anchor" href="#_2-3-配置-containerd-使用-systemd-cgroup"><span>2.3 配置 containerd 使用 systemd cgroup</span></a></h3><p>在 Kubernetes 环境中，kubelet 通常期望 containerd 使用 systemd cgroup 驱动。若未配置，可能导致 <code>kubeadm init</code> 失败或节点 NotReady：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 生成默认配置</span></span>
<span class="line"><span style="color:#61AFEF;">mkdir</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> /etc/containerd</span></span>
<span class="line"><span style="color:#61AFEF;">containerd</span><span style="color:#98C379;"> config</span><span style="color:#98C379;"> default</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">tee</span><span style="color:#98C379;"> /etc/containerd/config.toml</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 将 SystemdCgroup 改为 true</span></span>
<span class="line"><span style="color:#61AFEF;">sed</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> &#39;s/SystemdCgroup = false/SystemdCgroup = true/g&#39;</span><span style="color:#98C379;"> /etc/containerd/config.toml</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 启动 containerd 并配置开机自启</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> daemon-reload</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> enable</span><span style="color:#D19A66;"> --now</span><span style="color:#98C379;"> containerd</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 再次确认nerdctl就看不到报错了，并且还显示了server的版本</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> version</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133333444.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h3 id="_2-4-buildkit-配置-构建镜像必需" tabindex="-1"><a class="header-anchor" href="#_2-4-buildkit-配置-构建镜像必需"><span>2.4 BuildKit 配置（构建镜像必需）</span></a></h3><p>若使用完整包安装，BuildKit 已包含在内。启动 BuildKit 守护进程：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 启动 buildkitd（通常在安装 full 包后已自动配置为 systemd 服务）</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> daemon-reload</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> enable</span><span style="color:#D19A66;"> --now</span><span style="color:#98C379;"> buildkit</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对于 Rootless 模式，需要使用专用命令安装 BuildKit，如果是使用root用户，则不需要执行：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">containerd-rootless-setuptool.sh</span><span style="color:#98C379;"> install-buildkit</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="三、nerdctl-的基础使用" tabindex="-1"><a class="header-anchor" href="#三、nerdctl-的基础使用"><span>三、nerdctl 的基础使用</span></a></h2><h3 id="_3-1-核心命令" tabindex="-1"><a class="header-anchor" href="#_3-1-核心命令"><span>3.1 核心命令</span></a></h3><p><code>nerdctl</code> 命令与 <code>Docker</code> 命令几乎一致，以下是常用命令的对照：</p><table><thead><tr><th>Docker 命令</th><th>nerdctl 命令</th><th>说明</th></tr></thead><tbody><tr><td><code>docker run -it --rm nginx:1.24.0</code></td><td><code>nerdctl run -it --rm nginx:1.24.0</code></td><td>运行容器</td></tr><tr><td><code>docker pull nginx:1.24.0</code></td><td><code>nerdctl pull nginx:1.24.0</code></td><td>拉取镜像</td></tr><tr><td><code>docker build -t nginx:new .</code></td><td><code>nerdctl build -t nginx:new .</code></td><td>构建镜像（需 BuildKit）</td></tr><tr><td><code>docker compose up</code></td><td><code>nerdctl compose up</code></td><td>Compose 编排</td></tr><tr><td><code>docker login</code></td><td><code>nerdctl login</code></td><td>登录镜像仓库</td></tr><tr><td><code>docker ps -a</code></td><td><code>nerdctl ps -a</code></td><td>查看容器</td></tr><tr><td><code>docker logs -f &lt;id&gt;</code></td><td><code>nerdctl logs -f &lt;id&gt;</code></td><td>查看日志</td></tr><tr><td><code>docker ps -a --format &quot;{{.Names}}&quot;</code></td><td><code>nerdctl ps -a --format &quot;{{.Names}}&quot;</code></td><td>格式化输出容器名</td></tr></tbody></table><blockquote><p>nerdctl 的 <code>--format</code> 支持与 Docker 相同的 Go 模板语法，常用的占位符包括 <code>.Names</code>、<code>.ID</code>、<code>.Image</code>、<code>.Status</code> 等。此外 nerdctl 还额外支持 <code>--format=wide</code> 和 <code>--format=json</code> 等预设格式。</p></blockquote><blockquote><p>更多命令可参考Docker的用法，包括 <strong>镜像管理、容器管理、网络管理</strong>：<a href="https://liucy.blog.csdn.net/article/details/123842609#Docker_166" target="_blank" rel="noopener noreferrer">【Linux】部署Docker及镜像、容器、网络管理命令详解（步骤超全，含带发展史及核心概念）</a></p></blockquote><h3 id="_3-2-nerdctl-配置镜像加速地址" tabindex="-1"><a class="header-anchor" href="#_3-2-nerdctl-配置镜像加速地址"><span>3.2 nerdctl 配置镜像加速地址</span></a></h3><blockquote><p>既然docker都需要配置了，那么 <strong>nerdctl</strong> 和 <strong>docker</strong> 是同样的道理，拉取镜像都是从dockerhub里拉取，国内是拉取不到的，所以需要采用镜像加速源的方式来拉取镜像；<br> 但不同的是，配置文件位置不同，<strong>docker</strong> 的配置文件在：<code>/etc/docker/daemon.json</code>，<strong>nerdctl</strong> 的配置文件在：<code>/etc/containerd/config.toml</code></p></blockquote><p>如果没有找到<code>nerdctl</code>的配置的话应该是没有执行上面命令生成默认的配置，可使用命令：<code>containerd config default | tee /etc/containerd/config.toml</code></p><ul><li>开始配置镜像加速地址</li></ul><p><strong>1. 修改主配置</strong></p><p>编辑 <code>/etc/containerd/config.toml</code>，把 <code>config_path</code> 从空值改成目录：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 进入container配置文件</span></span>
<span class="line"><span style="color:#61AFEF;">vim</span><span style="color:#98C379;"> /etc/containerd/config.toml</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 找到 confing_path，默认应该在31行，然后配置是空的，修改为如下：</span></span>
<span class="line"><span style="color:#ABB2BF;">    [plugins.</span><span style="color:#98C379;">&#39;io.containerd.cri.v1.images&#39;</span><span style="color:#ABB2BF;">.registry]</span></span>
<span class="line"><span style="color:#61AFEF;">      config_path</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> &#39;/etc/containerd/certs.d&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133355800.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>2. 创建目录和文件</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">mkdir</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> /etc/containerd/certs.d/docker.io</span></span>
<span class="line"><span style="color:#61AFEF;">vi</span><span style="color:#98C379;"> /etc/containerd/certs.d/docker.io/hosts.toml</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 将如下配置添加到配置文件里</strong></p><blockquote><p>镜像加速地址可参考（长期维护）：</p><ul><li><a href="https://liucy.blog.csdn.net/article/details/129085538" target="_blank" rel="noopener noreferrer">【Docker】完美解决拉取镜像超时报错：ERROR: Get https://registry-1.docker.io/v2/</a></li><li><a href="https://www.liuchenyang.top/document/Docker/registry-1.docker.iov2.html#%E4%B8%89%E3%80%81%E8%A7%A3%E5%86%B3%E6%96%B9%E6%B3%951-%E6%9B%B4%E6%8D%A2docker%E4%B8%8B%E8%BD%BD%E6%BA%90" target="_blank" rel="noopener noreferrer">【Docker】完美解决拉取镜像超时报错：ERROR: Get https://registry-1.docker.io/v2/ -ToLiucyLinux</a></li><li><a href="https://mp.weixin.qq.com/mp/appmsgalbum?__biz=MzkwNzI2ODUwMg==&amp;action=getalbum&amp;album_id=4160135931510620166" target="_blank" rel="noopener noreferrer">Docker 镜像加速地址 - 公众号标签（每个月都会更新）</a><br><br><br> 可以按照上述任意一篇文章中的加速地址放到配置文件里进行修改，格式和Docker不一样，可参考下面写好的；</li></ul></blockquote><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">server</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> &quot;https://registry-1.docker.io&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://docker.apiba.cn&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub1.nat.tf&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://docker.1panel.live&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://dockerproxy.net&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub3.nat.tf&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub.1panel.dev&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://docker.367231.xyz&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://docker-registry.nmqu.com&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub2.nat.tf&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://docker.jsdelivr.fyi&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub.rat.dev&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub.fast360.xyz&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">[host.</span><span style="color:#98C379;">&quot;https://hub.amingg.com&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#61AFEF;">  capabilities</span><span style="color:#98C379;"> =</span><span style="color:#ABB2BF;"> [</span><span style="color:#98C379;">&quot;pull&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;resolve&quot;]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>4. 重启并验证</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 加载配置文件</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> daemon-reload</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 重启containerd服务</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> restart</span><span style="color:#98C379;"> containerd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 拉取镜像</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> pull</span><span style="color:#98C379;"> nginx:1.24.0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><figure><img src="https://gcore.jsdelivr.net/gh/liuchenyang0703/blog-images@main/images/20261024133402705.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><blockquote><p><strong>两点提醒</strong><br><strong>第一，<code>server</code> 字段的作用</strong>：它指定回退的原始地址。当所有 <code>[host.*]</code> 都失败时，containerd 会尝试直连 <code>server</code> 指定的地址。保留 <code>https://registry-1.docker.io</code> 作为兜底是标准做法。<br><strong>第二，地址顺序即尝试顺序</strong>：containerd 会按 <code>hosts.toml</code> 中 <code>[host.*]</code> 出现的<strong>从上到下</strong>顺序依次尝试。所以建议把<strong>实测最快、最稳定</strong>的地址放在最前面，比如 Docker 里排第一的 <code>docker.apiba.cn</code>。如果某些地址已失效，containerd 会在超时后自动跳到下一个，但会拖慢首次拉取速度——建议定期清理失效地址。</p></blockquote><h3 id="_3-3-数据默认存储路径及修改数据存储路径" tabindex="-1"><a class="header-anchor" href="#_3-3-数据默认存储路径及修改数据存储路径"><span>3.3 数据默认存储路径及修改数据存储路径</span></a></h3><h4 id="_3-3-1-数据默认存储路径" tabindex="-1"><a class="header-anchor" href="#_3-3-1-数据默认存储路径"><span>3.3.1 数据默认存储路径</span></a></h4><table><thead><tr><th>数据类型</th><th>管理组件</th><th>默认路径（rootful）</th></tr></thead><tbody><tr><td><strong>镜像内容 (Content Store)</strong></td><td>containerd</td><td><code>/var/lib/containerd/io.containerd.content.v1.content</code></td></tr><tr><td><strong>容器快照 (Snapshots)</strong></td><td>containerd</td><td><code>/var/lib/containerd/io.containerd.snapshotter.v1.overlayfs</code></td></tr><tr><td><strong>运行时状态 (State)</strong></td><td>containerd</td><td><code>/run/containerd</code></td></tr><tr><td><strong>nerdctl 自身元数据</strong></td><td>nerdctl</td><td><code>/var/lib/nerdctl</code></td></tr><tr><td><strong>nerdctl 配置文件</strong></td><td>nerdctl</td><td><code>/etc/containerd/config.toml</code></td></tr></tbody></table><blockquote><p><code>root</code> 目录（<code>/var/lib/containerd</code>）是持久化存储的核心，镜像和容器快照都在这里。<code>state</code> 目录（<code>/run/containerd</code>）存放运行时临时数据，<strong>重启后会重建</strong>，所以不要往这里放重要数据。</p></blockquote><h4 id="_3-3-2-修改数据存储路径" tabindex="-1"><a class="header-anchor" href="#_3-3-2-修改数据存储路径"><span>3.3.2 修改数据存储路径</span></a></h4><p>修改的主要是 containerd 的 <strong><code>root</code></strong> 字段，即数据根目录。<code>state</code> 目录一般保持默认即可。</p><p><strong>1. 编辑 <code>/etc/containerd/config.toml</code></strong></p><p>找到顶部的 <code>root</code> 字段并修改：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">version</span><span style="color:#98C379;"> =</span><span style="color:#D19A66;"> 4</span></span>
<span class="line"><span style="color:#61AFEF;">root</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> &#39;/data/containerd&#39;</span><span style="color:#7F848E;font-style:italic;">          # 改成你想要的新路径</span></span>
<span class="line"><span style="color:#61AFEF;">state</span><span style="color:#98C379;"> =</span><span style="color:#98C379;"> &#39;/run/containerd&#39;</span><span style="color:#7F848E;font-style:italic;">          # 通常不动</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2. 停服务，迁移已有数据</strong></p><p>这一步是<strong>必须的</strong>，不能跳过：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> stop</span><span style="color:#98C379;"> containerd</span></span>
<span class="line"><span style="color:#61AFEF;">mkdir</span><span style="color:#D19A66;"> -p</span><span style="color:#98C379;"> /data/containerd</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 rsync 或 cp -a 保留权限属性</span></span>
<span class="line"><span style="color:#61AFEF;">cp</span><span style="color:#D19A66;"> -a</span><span style="color:#98C379;"> /var/lib/containerd/.</span><span style="color:#98C379;"> /data/containerd/</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 启动并验证</strong></p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> daemon-reload</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#98C379;"> start</span><span style="color:#98C379;"> containerd</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> images</span><span style="color:#7F848E;font-style:italic;">   # 确认之前拉取的镜像还在</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-构建镜像" tabindex="-1"><a class="header-anchor" href="#_3-4-构建镜像"><span>3.4 构建镜像</span></a></h3><p>构建镜像需要 BuildKit 支持。与 Docker 不同，nerdctl build 会优先从仓库拉取基础镜像，而非直接使用本地缓存：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 基础构建</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> build</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> my-app:latest</span><span style="color:#98C379;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 构建并输出到本地目录（不生成镜像）</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> build</span><span style="color:#D19A66;"> -o</span><span style="color:#98C379;"> type=local,dest=.</span><span style="color:#98C379;"> .</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-镜像仓库登录" tabindex="-1"><a class="header-anchor" href="#_3-5-镜像仓库登录"><span>3.5 镜像仓库登录</span></a></h3><p>nerdctl 支持复用 Docker 的凭据配置（<code>~/.docker/config.json</code>），也支持独立登录：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 登录镜像仓库（将 docker login 替换为 nerdctl login）</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> login</span><span style="color:#D19A66;"> -u</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">usernam</span><span style="color:#ABB2BF;">e&gt; </span><span style="color:#D19A66;">-p</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">passwor</span><span style="color:#ABB2BF;">d&gt; &lt;</span><span style="color:#98C379;">registr</span><span style="color:#ABB2BF;">y&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 若遇到证书问题（如自签名证书），可添加 --insecure-registry</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> login</span><span style="color:#D19A66;"> --insecure-registry</span><span style="color:#D19A66;"> -u</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">usernam</span><span style="color:#ABB2BF;">e&gt; &lt;</span><span style="color:#98C379;">registr</span><span style="color:#ABB2BF;">y&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="四、与-kubernetes-集成" tabindex="-1"><a class="header-anchor" href="#四、与-kubernetes-集成"><span>四、与 Kubernetes 集成</span></a></h2><p>nerdctl 的一个重要特性是支持 containerd 的命名空间机制。Kubernetes 默认使用 <code>k8s.io</code> 命名空间运行所有容器，nerdctl 可以直接操作该命名空间下的资源。</p><h3 id="_4-1-查看-kubernetes-容器" tabindex="-1"><a class="header-anchor" href="#_4-1-查看-kubernetes-容器"><span>4.1 查看 Kubernetes 容器</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 列出 k8s.io 命名空间下的所有容器</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#D19A66;"> --namespace</span><span style="color:#98C379;"> k8s.io</span><span style="color:#98C379;"> ps</span><span style="color:#D19A66;"> -a</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>输出示例：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">CONTAINER</span><span style="color:#98C379;"> ID</span><span style="color:#98C379;">    IMAGE</span><span style="color:#98C379;">                                                      COMMAND</span><span style="color:#98C379;">                   CREATED</span><span style="color:#98C379;">          STATUS</span><span style="color:#98C379;">    PORTS</span><span style="color:#98C379;">    NAMES</span></span>
<span class="line"><span style="color:#61AFEF;">e8793b8cca8b</span><span style="color:#98C379;">    registry.k8s.io/coredns/coredns:v1.9.3</span><span style="color:#98C379;">                     &quot;/coredns -conf /etc…&quot;</span><span style="color:#D19A66;">    2</span><span style="color:#98C379;"> minutes</span><span style="color:#98C379;"> ago</span><span style="color:#98C379;">    Up</span><span style="color:#98C379;">                 k8s://kube-system/coredns-787d4945fb-mfx6b/coredns</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-构建镜像供-kubernetes-使用" tabindex="-1"><a class="header-anchor" href="#_4-2-构建镜像供-kubernetes-使用"><span>4.2 构建镜像供 Kubernetes 使用</span></a></h3><p>无需推送至镜像仓库，直接在本地构建并供 kubelet 使用：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 在 k8s.io 命名空间下构建镜像</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#D19A66;"> --namespace</span><span style="color:#98C379;"> k8s.io</span><span style="color:#98C379;"> build</span><span style="color:#D19A66;"> -t</span><span style="color:#98C379;"> my-app:latest</span><span style="color:#98C379;"> /path/to/dockerfile-dir</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看镜像</span></span>
<span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#D19A66;"> --namespace</span><span style="color:#98C379;"> k8s.io</span><span style="color:#98C379;"> images</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 在 Pod 中引用（imagePullPolicy 需设为 Never 或 IfNotPresent）</span></span>
<span class="line"><span style="color:#61AFEF;">kubectl</span><span style="color:#98C379;"> apply</span><span style="color:#D19A66;"> -f</span><span style="color:#98C379;"> -</span><span style="color:#ABB2BF;"> &lt;&lt;</span><span style="color:#ABB2BF;">EOF</span></span>
<span class="line"><span style="color:#98C379;">apiVersion: v1</span></span>
<span class="line"><span style="color:#98C379;">kind: Pod</span></span>
<span class="line"><span style="color:#98C379;">metadata:</span></span>
<span class="line"><span style="color:#98C379;">  name: my-app</span></span>
<span class="line"><span style="color:#98C379;">spec:</span></span>
<span class="line"><span style="color:#98C379;">  containers:</span></span>
<span class="line"><span style="color:#98C379;">  - name: my-app</span></span>
<span class="line"><span style="color:#98C379;">    image: my-app:latest</span></span>
<span class="line"><span style="color:#98C379;">    imagePullPolicy: Never</span></span>
<span class="line"><span style="color:#ABB2BF;">EOF</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-加载镜像归档" tabindex="-1"><a class="header-anchor" href="#_4-3-加载镜像归档"><span>4.3 加载镜像归档</span></a></h3><p>支持导入 <code>docker save</code> 格式或 OCI 格式的镜像归档：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#D19A66;"> --namespace</span><span style="color:#98C379;"> k8s.io</span><span style="color:#98C379;"> load</span><span style="color:#ABB2BF;"> &lt; </span><span style="color:#98C379;">/path/to/image.tar</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="五、rootless-模式" tabindex="-1"><a class="header-anchor" href="#五、rootless-模式"><span>五、Rootless 模式</span></a></h2><p>Rootless 模式允许非 root 用户运行 containerd 和容器，适用于多用户开发环境或安全要求较高的场景。nerdctl 提供了 <code>containerd-rootless-setuptool.sh</code> 脚本简化配置。</p><h3 id="_5-1-安装-rootless-containerd" tabindex="-1"><a class="header-anchor" href="#_5-1-安装-rootless-containerd"><span>5.1 安装 Rootless containerd</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用完整包中的脚本进行安装</span></span>
<span class="line"><span style="color:#61AFEF;">containerd-rootless-setuptool.sh</span><span style="color:#98C379;"> install</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本会自动完成以下工作：</p><ul><li>检查 RootlessKit 功能、cgroup v2、overlayfs 支持</li><li>创建 systemd 用户服务 <code>~/.config/systemd/user/containerd.service</code></li><li>启动并启用 containerd 服务</li></ul><h3 id="_5-2-使用-rootless-nerdctl" tabindex="-1"><a class="header-anchor" href="#_5-2-使用-rootless-nerdctl"><span>5.2 使用 Rootless nerdctl</span></a></h3><p>安装完成后，直接执行 nerdctl 即可，<strong>无需手动指定 <code>$CONTAINERD_ADDRESS</code></strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">nerdctl</span><span style="color:#98C379;"> run</span><span style="color:#D19A66;"> -it</span><span style="color:#D19A66;"> --rm</span><span style="color:#98C379;"> alpine</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_5-3-管理-rootless-服务" tabindex="-1"><a class="header-anchor" href="#_5-3-管理-rootless-服务"><span>5.3 管理 Rootless 服务</span></a></h3><p>Rootless 模式下服务由用户级 systemd 管理：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 控制服务</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#D19A66;"> --user</span><span style="color:#98C379;"> start</span><span style="color:#ABB2BF;">|</span><span style="color:#61AFEF;">stop</span><span style="color:#ABB2BF;">|</span><span style="color:#61AFEF;">restart</span><span style="color:#98C379;"> containerd.service</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 查看状态</span></span>
<span class="line"><span style="color:#61AFEF;">systemctl</span><span style="color:#D19A66;"> --user</span><span style="color:#98C379;"> status</span><span style="color:#98C379;"> containerd.service</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-4-开机自启动" tabindex="-1"><a class="header-anchor" href="#_5-4-开机自启动"><span>5.4 开机自启动</span></a></h3><p>若希望容器在用户未登录时也能运行，需启用 linger：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> loginctl</span><span style="color:#98C379;"> enable-linger</span><span style="color:#ABB2BF;"> &lt;</span><span style="color:#98C379;">usernam</span><span style="color:#ABB2BF;">e&gt;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_5-5-资源限制的约束" tabindex="-1"><a class="header-anchor" href="#_5-5-资源限制的约束"><span>5.5 资源限制的约束</span></a></h3><p>Rootless 模式下，<code>--cpus</code>、<code>--memory</code> 等资源限制标志需要满足以下条件才能生效：</p><ul><li>containerd 1.4+</li><li>runc 1.0-rc91+</li><li>cgroup v2</li><li>systemd</li></ul><p>若内核版本较低（&lt; 5.13）或使用 SELinux，可能需要切换至 <code>fuse-overlayfs</code> snapshotter：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 安装 fuse-overlayfs</span></span>
<span class="line"><span style="color:#61AFEF;">containerd-rootless-setuptool.sh</span><span style="color:#98C379;"> install-fuse-overlayfs</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 设置环境变量后使用</span></span>
<span class="line"><span style="color:#C678DD;">export</span><span style="color:#E06C75;"> CONTAINERD_SNAPSHOTTER</span><span style="color:#56B6C2;">=</span><span style="color:#E06C75;">fuse-overlayfs</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、总结" tabindex="-1"><a class="header-anchor" href="#六、总结"><span>六、总结</span></a></h2><p>nerdctl 的核心价值在于：<strong>在不牺牲 containerd 原生能力的前提下，提供了 Docker 级别的用户体验</strong>。对于已经从 Docker 迁移至 containerd 的 Kubernetes 环境，nerdctl 是最顺手的日常操作工具；对于希望探索 containerd 生态的开发者，nerdctl 也是比 <code>ctr</code> 更友好的入门选择。</p><p>从部署角度看，推荐直接使用 <code>nerdctl-full</code> 包一次性配齐所有依赖。在 Kubernetes 节点上，重点关注 <code>SystemdCgroup = true</code> 的配置以及 <code>--namespace k8s.io</code> 的使用习惯。Rootless 模式虽然能提升隔离性，但对内核版本和 cgroup 版本有一定要求，部署前需确认环境兼容性。</p>`,138)]])}var s=n(a,[[`render`,o]]);export{i as _pageData,s as default};